#!/usr/bin/env Rscript
# Group comparison of cell-type-specific scCRS cytokine-response scores.
suppressPackageStartupMessages({ library(optparse); library(ggplot2); library(dplyr); library(patchwork); library(Cairo) })
opts <- list(
 make_option('--input',type='character',help='cell_type_cytokine_scores_with_group.csv'), make_option('--outdir',type='character',default='sccrs_group_celltype_response'),
 make_option('--score-col',dest='score_col',type='character',default='raw_rank_score'), make_option('--patient-col',dest='patient_col',type='character',default='patient_id'), make_option('--group-col',dest='group_col',type='character',default='group'), make_option('--cytokines',type='character',default='IFN-α1,IFN-β,IFN-γ,IFN-ε,IFN-κ,IFN-λ2'), make_option('--cell-types',dest='cell_types',type='character',default=NULL), make_option('--group-order',dest='group_order',type='character',default=NULL), make_option('--group-labels',dest='group_labels',type='character',default=NULL), make_option('--ncol',type='integer',default=4)
)
a <- parse_args(OptionParser(option_list=opts)); if(is.null(a$input)) stop('Required: --input'); dir.create(a$outdir,recursive=TRUE,showWarnings=FALSE)
x <- read.csv(a$input,check.names=FALSE,stringsAsFactors=FALSE); need <- c(a$patient_col,a$group_col,'cell_type','cytokine',a$score_col); miss <- setdiff(need,names(x)); if(length(miss)) stop('Missing columns: ',paste(miss,collapse=', '))
cy <- trimws(strsplit(a$cytokines,',',fixed=TRUE)[[1]]); ct <- if(is.null(a$cell_types)) sort(unique(as.character(x$cell_type))) else trimws(strsplit(a$cell_types,',',fixed=TRUE)[[1]])
x <- x %>% transmute(patient_id=as.character(.data[[a$patient_col]]),group=as.character(.data[[a$group_col]]),cell_type=as.character(cell_type),cytokine=as.character(cytokine),score=as.numeric(.data[[a$score_col]])) %>% filter(cytokine %in% cy,cell_type %in% ct,is.finite(score))
if(!nrow(x)) stop('No rows remain after cytokine/cell-type filtering.')
lev <- if(is.null(a$group_order)) sort(unique(x$group)) else trimws(strsplit(a$group_order,',',fixed=TRUE)[[1]]); lab <- if(is.null(a$group_labels)) lev else trimws(strsplit(a$group_labels,',',fixed=TRUE)[[1]]); if(length(lab)!=length(lev)) stop('--group-labels must have same length as --group-order.'); x$group <- factor(x$group,levels=lev,labels=lab); ct <- ct[ct %in% unique(x$cell_type)]
comparisons <- combn(lab,2,simplify=FALSE); star <- function(q) ifelse(is.na(q),'ns',ifelse(q<=.001,'***',ifelse(q<=.01,'**',ifelse(q<=.05,'*','ns'))))
tests <- bind_rows(lapply(cy,function(c0) bind_rows(lapply(ct,function(t0) { d <- filter(x,cytokine==c0,cell_type==t0); ans <- bind_rows(lapply(comparisons,function(pair) { u <- d$score[d$group==pair[1]]; v <- d$score[d$group==pair[2]]; if(length(u)<2||length(v)<2) return(data.frame(cytokine=c0,cell_type=t0,group_1=pair[1],group_2=pair[2],n_group_1=length(u),n_group_2=length(v),statistic=NA_real_,p_value=NA_real_)); w <- suppressWarnings(wilcox.test(u,v,exact=FALSE)); data.frame(cytokine=c0,cell_type=t0,group_1=pair[1],group_2=pair[2],n_group_1=length(u),n_group_2=length(v),statistic=unname(w$statistic),p_value=w$p.value) })); ans$p_adjust_bh <- p.adjust(ans$p_value,'BH'); ans$significance <- star(ans$p_adjust_bh); ans }))))
write.csv(tests,file.path(a$outdir,'group_pairwise_wilcoxon_statistics.csv'),row.names=FALSE); write.csv(x,file.path(a$outdir,'group_celltype_response_violin_plotting_data.csv'),row.names=FALSE)
pdf_path <- file.path(a$outdir,'scCRS_group_celltype_response_violin_plots.pdf'); CairoPDF(pdf_path,width=14,height=8.8,onefile=TRUE)
for(c0 in cy) { panels <- lapply(ct,function(t0) { d <- filter(x,cytokine==c0,cell_type==t0); st <- filter(tests,cytokine==c0,cell_type==t0,significance!='ns'); if(!nrow(d)) return(ggplot()+theme_void()+labs(title=t0)); r <- range(d$score); span <- diff(r); if(!is.finite(span)||span==0) span <- max(abs(r),1)*.2; top <- r[2]+max(.16,.20*span*nrow(st)+.12*span); p <- ggplot(d,aes(group,score,fill=group))+geom_violin(trim=TRUE,alpha=.65,colour='grey25',linewidth=.35)+geom_boxplot(width=.15,outlier.shape=NA,fill='white',linewidth=.35)+geom_jitter(aes(colour=group),width=.10,size=1.25,alpha=.8,show.legend=FALSE)+stat_summary(fun=median,geom='point',shape=95,size=5)+coord_cartesian(ylim=c(r[1]-.25*span,top),clip='on')+labs(title=t0,x=NULL,y=a$score_col)+theme_bw(base_size=10)+theme(panel.grid=element_blank(),panel.border=element_rect(colour='black',fill=NA),axis.text.x=element_blank(),axis.ticks.x=element_blank(),plot.title=element_text(hjust=.5,face='bold',size=10)); if(nrow(st)) { st <- arrange(st,p_adjust_bh) %>% mutate(x1=match(group_1,lab),x2=match(group_2,lab),xmid=(x1+x2)/2,y=r[2]+seq_len(n())*.20*span,tick=.035*span); p <- p+geom_segment(data=st,aes(x=x1,xend=x2,y=y,yend=y),inherit.aes=FALSE)+geom_segment(data=st,aes(x=x1,xend=x1,y=y,yend=y-tick),inherit.aes=FALSE)+geom_segment(data=st,aes(x=x2,xend=x2,y=y,yend=y-tick),inherit.aes=FALSE)+geom_text(data=st,aes(x=xmid,y=y+.035*span,label=significance),inherit.aes=FALSE,size=4.2) }; p }); print(wrap_plots(panels,ncol=a$ncol)+plot_annotation(title=paste0(c0,' response across patient groups and immune cell types'),subtitle='Points are patients; brackets denote BH-adjusted pairwise Wilcoxon significance')) }
dev.off(); cat('Wrote group comparison plots to ',a$outdir,'\n',sep='')
